# Cell 2
EXPECTED_CACHE = {'aligned_pair_side_metadata.csv': 'f48c7105ab3350f559a691988dcfbbae49087c334e8db8bb4a76225feb893e03', 'aligned_pair_side_embeddings.npy': 'a899bf866695c2e470d4ec039b2918dbc764c5c44955241fd62ff93c6c8d6824'}
