# Cell 4
def load_cache_bytes():
    roots = [Path(CACHE_DIR)] if CACHE_DIR else [INPUT_ROOT]
    found = {n: [] for n in EXPECTED_CACHE}
    for root in roots:
        for name in found:
            for p in sorted(root.rglob(name)):
                found[name].append((str(p), p.read_bytes()))
        for p in sorted(root.rglob('*.zip')):
            with zipfile.ZipFile(p) as z:
                for member in z.namelist():
                    name = Path(member).name
                    if name in found:
                        found[name].append((str(p)+'::'+member, z.read(member)))
    result, provenance = {}, []
    for name, versions in found.items():
        if not versions:
            raise FileNotFoundError(f'Attach the aligned embedding cache: missing {name}')
        bad = [p for p,b in versions if sha(b) != EXPECTED_CACHE[name]]
        if bad:
            raise ValueError(f'Conflicting cache version for {name}: {bad}. Set CACHE_DIR to the correct input folder.')
        result[name] = versions[0][1]
        provenance.append(dict(file=name, sha256=sha(versions[0][1]), locations=[p for p,b in versions]))
    return result, provenance
raw, cache_provenance = load_cache_bytes()
