# Cell 6
def unit(a):
    n = np.linalg.norm(a,axis=1,keepdims=True)
    assert np.isfinite(a).all()
    return a / np.maximum(n,1e-12)
def make_gallery(rows):
    people = np.sort(df.iloc[rows].identity.unique())
    frontal = df.iloc[rows].query("pose == 'frontal'")
    G = unit(np.stack([X[frontal.loc[frontal.identity.eq(i),'row']].mean(axis=0) for i in people]))
    probes = df.iloc[rows].query("pose == 'profile'").row.to_numpy()
    assert len(probes)>0 and len(people)>5
    return people, G, probes
splits = []
partition_records = []
for seed in SPLIT_SEEDS:
    people = np.random.default_rng(seed).permutation(np.sort(df.identity.unique()))
    parts = dict(train=people[:350], validation=people[350:425], test=people[425:])
    assert all(len(set(parts[a])&set(parts[b]))==0 for a,b in [('train','validation'),('train','test'),('validation','test')])
    rows = {k:df.loc[df.identity.isin(v),'row'].to_numpy() for k,v in parts.items()}
    for a,b in [('train','validation'),('train','test'),('validation','test')]:
        assert not set(df.iloc[rows[a]].source_pixel_sha256)&set(df.iloc[rows[b]].source_pixel_sha256)
        assert not set(df.iloc[rows[a]].encoded_sha256)&set(df.iloc[rows[b]].encoded_sha256)
    splits.append((seed,rows,make_gallery(rows['validation']),make_gallery(rows['test'])))
    for part,identities in parts.items():
        partition_records.extend(dict(split_seed=seed, identity=int(i), partition=part) for i in identities)
pd.DataFrame(partition_records).to_csv(OUT/'identity_partitions.csv', index=False)
print('All three identity-disjoint split checks passed. 75-person galleries; random rank-1 chance = 1/75.')


# Cell 8
Q_all = []
key_manifest = []
for seed in KEY_SEEDS:
    A = np.random.default_rng(seed).standard_normal((512,512))
    Q,R = np.linalg.qr(A)
    sign = np.where(np.diag(R)<0,-1.0,1.0)
    Q = np.ascontiguousarray(Q*sign)
    assert np.allclose(Q.T@Q,np.eye(512),atol=1e-10)
    Q_all.append(Q)
    key_manifest.append(dict(seed=seed, matrix_sha256=sha(Q.tobytes())))
save_json('projection_keys.json',dict(algorithm='numpy default_rng PCG64; Gaussian float64; QR; nonnegative R diagonal', keys=key_manifest))
def backprojection_features(embeddings, bits):
    total = np.zeros_like(embeddings,dtype=np.float64)
    for k,Q in enumerate(Q_all,1):
        q = Q[:,:bits]
        signed_bits = np.where(embeddings@q >= 0,1.0,-1.0)
        total += signed_bits@q.T / np.sqrt(bits)
        if k in EXPOSURES:
            yield k, total.copy()/k

def ridge_components(F,Y):
    fm, ym = F.mean(axis=0),Y.mean(axis=0)
    A,B = F-fm,Y-ym
    eig,V = np.linalg.eigh(A.T@A/len(A))
    cross = V.T@(A.T@B/len(A))
    return fm,ym,np.maximum(eig,0),V,cross

def ridge_weights(parts,alpha):
    fm,ym,eig,V,cross=parts
    W = V@(cross/(eig[:,None]+alpha))
    return W,ym-fm@W

def identify(reconstructed, gallery):
    people,G,probe_rows=gallery
    scores=unit(reconstructed)@G.T
    # mergesort yields deterministic gallery-ID ordering when scores tie.
    order=np.argsort(-scores,axis=1,kind='stable')
    truth=df.iloc[probe_rows].identity.to_numpy()
    pred=people[order[:,0]]
    hit1=pred==truth
    hit5=(people[order[:,:5]]==truth[:,None]).any(axis=1)
    macro=pd.DataFrame(dict(identity=truth,hit=hit1)).groupby('identity').hit.mean().mean()
    cosine=np.sum(unit(reconstructed)*X[probe_rows],axis=1)
    metrics=dict(probes=len(truth), gallery_identities=len(people), rank1_micro=float(hit1.mean()),
        rank1_macro=float(macro), rank5_micro=float(hit5.mean()), mean_cosine_to_raw=float(cosine.mean()),
        zero_reconstructions=int((np.linalg.norm(reconstructed,axis=1)<1e-12).sum()),
        chance_rank1=1/len(people), chance_rank5=5/len(people))
    per_probe=pd.DataFrame(dict(row=probe_rows,encoded_sha256=df.iloc[probe_rows].encoded_sha256.to_numpy(),
        identity=truth,predicted_identity=pred,rank1=hit1,rank5=hit5,cosine_to_raw=cosine))
    return metrics,per_probe


# Cell 10
results, predictions, tuning = [], [], []
for seed,rows,val_gallery,test_gallery in splits:
    m,p=identify(X[test_gallery[2]],test_gallery)
    results.append(dict(split_seed=seed,method='raw_reference',bits=0,K=0,alpha=0.0,**m))
    predictions.append(p.assign(split_seed=seed,method='raw_reference',bits=0,K=0))
for bits in DIMENSIONS:
    for k,F in backprojection_features(X,bits):
        for seed,rows,val_gallery,test_gallery in splits:
            parts=ridge_components(F[rows['train']],X[rows['train']])
            choices=[]
            for alpha in ALPHAS:
                W,bias=ridge_weights(parts,alpha)
                vm,_=identify(F[val_gallery[2]]@W+bias,val_gallery)
                choices.append((vm['rank1_macro'],alpha))
                tuning.append(dict(split_seed=seed,bits=bits,K=k,alpha=alpha,validation_rank1_macro=vm['rank1_macro']))
            best_val,best_alpha=max(choices)
            W,bias=ridge_weights(parts,best_alpha)
            # Save the selected attacker so its exact predictions are reproducible.
            np.savez_compressed(OUT/f'attacker_s{seed}_b{bits}_k{k}.npz',W=W,bias=bias,alpha=best_alpha)
            for method,reconstructed in [
                ('untrained_backprojection',F[test_gallery[2]]),
                ('ridge_reconstruction',F[test_gallery[2]]@W+bias)]:
                m,p=identify(reconstructed,test_gallery)
                results.append(dict(split_seed=seed,method=method,bits=bits,K=k,
                    alpha=best_alpha if method=='ridge_reconstruction' else 0.0,**m))
                predictions.append(p.assign(split_seed=seed,method=method,bits=bits,K=k))
            print(f'bits={bits}, K={k}, split={seed}: ridge test macro rank-1={results[-1]["rank1_macro"]:.3f}',flush=True)
        # Incremental tables remain available if a later cell is interrupted.
        pd.DataFrame(results).to_csv(OUT/'results_by_split.csv',index=False)
result=pd.DataFrame(results)
pd.concat(predictions,ignore_index=True).to_csv(OUT/'test_probe_predictions.csv',index=False)
pd.DataFrame(tuning).to_csv(OUT/'validation_alpha_search.csv',index=False)
summary=result.groupby(['method','bits','K'],as_index=False).agg(
    rank1_macro_mean=('rank1_macro','mean'),rank1_macro_sd=('rank1_macro','std'),
    rank1_micro_mean=('rank1_micro','mean'),rank5_micro_mean=('rank5_micro','mean'),
    cosine_mean=('mean_cosine_to_raw','mean'),repeats=('split_seed','count'))
summary.to_csv(OUT/'summary.csv',index=False)
display(summary)


